class ConnectGame:
    def __init__(self, board):
        self.board = [line.split() for line in board.splitlines() if line]

    def get_winner(self):
        if self._connects("X", 0, -1):
            return "X"
        if self._connects("O", 0, len(self.board) - 1):
            return "O"
        return ""

    def _connects(self, player, start_row, end_row):
        rows = len(self.board)
        cols = len(self.board[0])
        seen = set()
        stack = [(r, c) for r in range(rows) for c in (0, cols - 1)
                 if self.board[r][c] == player]
        while stack:
            r, c = stack.pop()
            if (r, c) in seen:
                continue
            seen.add((r, c))
            if r in (start_row, end_row):
                return True
            for nr, nc in ((r, c - 1), (r, c + 1), (r - 1, c),
                           (r - 1, c + 1), (r + 1, c - 1), (r + 1, c)):
                if 0 <= nr < rows and 0 <= nc < cols and self.board[nr][nc] == player:
                    stack.append((nr, nc))
        return False

