class ConnectGame:
    def __init__(self, board):
        self.board = [line.split() for line in board.splitlines() if line]

    def get_winner(self):
        rows = len(self.board)
        cols = len(self.board[0])
        if self._connects("X", lambda r, c: c == 0, lambda r, c: c == cols - 1):
            return "X"
        if self._connects("O", lambda r, c: r == 0, lambda r, c: r == rows - 1):
            return "O"
        return ""

    def _connects(self, player, start, goal):
        rows = len(self.board)
        cols = len(self.board[0])
        seen = set()
        stack = [(r, c) for r in range(rows) for c in range(cols)
                 if self.board[r][c] == player and start(r, c)]
        while stack:
            r, c = stack.pop()
            if (r, c) in seen:
                continue
            seen.add((r, c))
            if goal(r, c):
                return True
            for nr, nc in ((r, c - 1), (r, c + 1), (r - 1, c),
                           (r - 1, c + 1), (r + 1, c - 1), (r + 1, c)):
                if 0 <= nr < rows and 0 <= nc < cols and self.board[nr][nc] == player:
                    stack.append((nr, nc))
        return False
